#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
        ops.push_back({x,y});
    };

    // Place elements 1, 2, ..., n-1 into positions 0, 1, ..., n-2
    for(int placed = 0; placed < n-1; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        int remaining = n - placed; // working with positions [placed..n-1]

        // We need to bring p[pos] to p[placed].
        // Strategy: first bring to last position (n-1), then bring to placed.

        // Step 1: bring to position n-1
        if(pos != n-1){
            // op(pos+1, n-1-pos): prefix=p[0..pos], suffix=p[pos+1..n-1]... wait need middle
            // x=pos+1, y=n-1-pos => x+y=n, invalid.
            // x=pos, y=n-1-pos: prefix=p[0..pos-1], suffix=p[pos+1..n-1], middle=p[pos..pos]
            // new: suffix + [p[pos]] + prefix. p[pos] at position (n-1-pos)+0 = n-1-pos. Not n-1.

            // Use: x=1, y=n-1-pos. new = suffix(n-1-pos) + middle(pos-0) + prefix(1)
            // p[pos] is in middle at index pos-1 within middle. Goes to (n-1-pos)+(pos-1)=n-2. Hmm.

            // Direct: x=pos+1, y=n-pos-2 (if valid). Element at pos = end of prefix -> goes to n-1.
            int x = pos+1, y = n-pos-2;
            if(x > 0 && y > 0 && x+y < n){
                apply_op(x, y);
            } else if(y == 0){
                // pos = n-2. Use op(1, 1): swap first and last around middle
                // Then re-find
                apply_op(1, 1);
                pos = -1;
                for(int i = placed; i < n; i++) if(p[i]==placed+1){pos=i;break;}
                if(pos==placed) continue;
                if(pos!=n-1){ int xx=pos+1,yy=n-pos-2; if(xx>0&&yy>0&&xx+yy<n) apply_op(xx,yy); }
            }
        }
        if(p[placed]==placed+1) continue;
        // Step 2: element at n-1, move to placed. op(placed, 1): suffix=[p[n-1]], middle, prefix
        // p[n-1] goes to position 0... we want it at placed.
        // op(placed+1,1) if placed+1+1<n: new=[p[n-1]]+middle+prefix. p[n-1] at 0. Nope.
        // Actually op with x=placed, y=1: new = [p[n-1]] + p[placed..n-2] + p[0..placed-1]. Target at 0.
        // Then op(1, n-1-placed): moves pos 0 to position n-1... not helpful.
        // op(n-1-placed, placed): suffix=p[n-placed..n-1]= last placed elems (already sorted), prefix=first n-1-placed
        // Hmm let me just use op(1, n-1-placed) after putting at 0
        if(p[n-1]==placed+1){
            apply_op(placed, 1);
            // now placed+1 is at position 0, need it at placed
            if(placed > 0) apply_op(1, n-1-placed);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
